import {pollenPathCopy as T,pollenPathContacts,pollenPathInvitations,pollenPathLessons} from './pollen-path-content.mjs';
import {changePollenPath,pollenPathModel,pollenPathNarration} from './pollen-path-core.mjs';

const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const button=(action,label,value='',extra='')=>`<button type="button" class="secondary" data-pollen-path-action="${action}" data-pollen-path-value="${esc(value)}" ${extra}>${esc(label)}</button>`;
const copy={...T,confirm:T.confirmation};

// Each symbol labels an origin; repeated shapes never stand for grain quantities.
function mark(origin,x=0,y=0){return `<g transform="translate(${x} ${y})" class="pollen-path-origin pollen-path-origin-${origin.toLowerCase()}">${origin==='A'?'<circle r="12"/>':'<path d="M0-15 15 0 0 15-15 0Z"/>'}<text text-anchor="middle" dy="5">${origin}</text></g>`;}
function marks(bits,x=0,y=0){return `<g transform="translate(${x} ${y})">${bits[0]?mark('A',bits[1]?-16:0,0):''}${bits[1]?mark('B',bits[0]?16:0,0):''}</g>`;}
function flower(x,label,bits=[false,false]){return `<g transform="translate(${x} 0)" class="pollen-path-flower"><path class="pollen-path-stem" d="M0 258v101m0-22q-55-40-67-12 26 32 67 12m0-9q51-39 64-17-22 30-64 17"/><path class="pollen-path-petal" d="M0 265C-38 246-114 225-111 158q37-13 67 40C-61 136-24 120 0 174c24-54 61-38 44 24q30-53 67-40C114 225 38 246 0 265Z"/><path class="pollen-path-filament" d="M-28 244-67 160m95 84 39-84"/><ellipse class="pollen-path-anther" cx="-70" cy="154" rx="19" ry="10" transform="rotate(-25 -70 154)"/><ellipse class="pollen-path-anther" cx="70" cy="154" rx="19" ry="10" transform="rotate(25 70 154)"/><path class="pollen-path-style" d="M0 244V119"/><path class="pollen-path-stigma" d="M-20 116q20-14 40 0v10q-20 12-40 0Z"/><ellipse class="pollen-path-nectar" cx="0" cy="250" rx="19" ry="8"/>${marks(bits,0,89)}<text class="pollen-path-flower-letter" x="0" y="299" text-anchor="middle">${label}</text></g>`;}
function bee(x,y,bits=[false,false],scale=1){return `<g class="pollen-path-bee" transform="translate(${x} ${y}) scale(${scale})"><g class="pollen-path-wings"><ellipse cx="-9" cy="-20" rx="12" ry="24" transform="rotate(-34 -9 -20)"/><ellipse cx="9" cy="-20" rx="12" ry="24" transform="rotate(34 9 -20)"/><ellipse cx="-13" cy="-2" rx="10" ry="19" transform="rotate(-60 -13 -2)"/><ellipse cx="13" cy="-2" rx="10" ry="19" transform="rotate(60 13 -2)"/></g><g class="pollen-path-legs"><path d="M-9-9-27-17-34-10M-11 0-30 4-35 15M-9 9-25 21-23 31M9-9 27-17 34-10M11 0 30 4 35 15M9 9 25 21 23 31"/></g><ellipse class="pollen-path-abdomen" cx="0" cy="25" rx="17" ry="25"/><path class="pollen-path-stripes" d="M-15 15h30m-32 13h34m-28 13h22"/><ellipse class="pollen-path-thorax" cx="0" cy="0" rx="15" ry="18"/><circle class="pollen-path-head" cx="0" cy="-29" r="13"/><path class="pollen-path-antennae" d="M-6-39-13-53-18-53M6-39 13-53 18-53"/><circle class="pollen-path-eye" cx="-5" cy="-31" r="2"/><circle class="pollen-path-eye" cx="5" cy="-31" r="2"/>${marks(bits,0,26)}</g>`;}
const positions={rest:[320,270],'a-anthers':[42,112],'a-stigma':[214,85],'a-nectar':[228,242],'b-anthers':[598,112],'b-stigma':[426,85],'b-nectar':[412,242]};
function gardenFigure(m){const [x,y]=positions[m.position]||positions.rest;return `<figure class="pollen-path-garden-figure"><svg class="pollen-path-picture" data-pollen-path-garden viewBox="0 0 640 380" role="img" aria-label="Conceptual cutaway of two flowers of the same kind and a paper bee. Each flower has separate anthers, a stigma and a nectar stop. The bee has a head, thorax and abdomen, six legs, four wings and two antennae. Current position and origin marks are described below." focusable="false"><path class="pollen-path-ground" d="M12 358q150-14 308 0t308 0"/>${flower(160,'A',m.stigmas[0])}${flower(480,'B',m.stigmas[1])}${bee(x,y,m.body,.78)}</svg><figcaption>${esc(copy.caption)}</figcaption></figure>`;}
function legendMarks(){return `<span class="pollen-path-mark-key"><svg viewBox="-19 -19 38 38" aria-hidden="true">${mark('A')}</svg><span>Origin A</span></span><span class="pollen-path-mark-key"><svg viewBox="-19 -19 38 38" aria-hidden="true">${mark('B')}</svg><span>Origin B</span></span>`;}
function flowerControls(label){return `<section class="pollen-path-contact-card"><h3>Flower ${label}</h3><div class="pollen-path-contact-buttons">${pollenPathContacts.filter(c=>c.flower===label).map(c=>button('contact',c.buttonLabel,c.id)).join('')}</div></section>`;}
function optionSelect(action,label,entries,index){return `<label class="pollen-path-select-label">${esc(label)}<select data-pollen-path-action="${action}">${entries.map((e,i)=>`<option value="${i}"${i===index?' selected':''}>${esc(e.title)}</option>`).join('')}</select></label>`;}
function workedFigure(index){let art='',key='';if(index===0){art=flower(210,'',[false,false]);key='<ul class="pollen-path-anatomy-key"><li><strong>Anthers</strong> · the two pollen-bearing tips to the sides</li><li><strong>Stigma</strong> · the central top, on its style</li><li><strong>Nectar stop</strong> · near the flower base</li></ul>';}
if(index===1){art=`<g transform="translate(4 0) scale(.48)">${flower(150,'A')}${bee(46,100,[true,false],.9)}</g><path class="pollen-path-order-arrow" d="M135 126h34m-9-8 9 8-9 8"/>${bee(211,120,[true,false],.8)}<path class="pollen-path-order-arrow" d="M251 126h34m-9-8 9 8-9 8"/><g transform="translate(270 0) scale(.48)">${flower(150,'B',[true,false])}${bee(245,81,[true,false],.9)}</g>`;key='<ol class="pollen-path-stage-key"><li>Touch A’s anthers.</li><li>Carry origin A on the body.</li><li>Bring origin A to B’s stigma.</li></ol>';}
if(index===2){art=`<path class="pollen-path-panel-divider" d="M210 18v172"/><g transform="translate(8 0) scale(.55)">${flower(165,'')}${bee(283,238,[true,false],.85)}</g><g transform="translate(223 0) scale(.55)">${flower(165,'')}${bee(127,122,[true,false],1.05)}<path class="pollen-path-possible" d="M137 136 165 122m-45 7-25 25"/></g>`;key='<div class="pollen-path-visit-key"><p><strong>Model · nectar stop only</strong><br>Pollen marks stay the same.</p><p><strong>Possible real visit · not a prediction</strong><br>A bee may brush nearby flower parts.</p></div>';}
if(index===3){art=`<g transform="translate(66 95)"><path class="pollen-path-filament" d="M0 58V10"/><ellipse class="pollen-path-anther" rx="24" ry="12"/></g><path class="pollen-path-order-arrow" d="M109 95h65m-10-8 10 8-10 8"/><g transform="translate(211 95)"><path class="pollen-path-style" d="M0 58V8"/><path class="pollen-path-stigma" d="M-22-7q22-13 44 0v11q-22 12-44 0Z"/>${mark('A',0,-27)}</g><path class="pollen-path-later" d="M251 95h94"/><text class="pollen-path-question" x="365" y="107">?</text>`;key='<div class="pollen-path-later-key"><span>Anther → stigma: pollen transfer</span><span>Later processes are not modeled</span></div>';}
return `<figure class="pollen-path-worked-figure" data-pollen-path-figure="${index}"><svg class="pollen-path-picture" viewBox="0 0 420 ${index===0?380:210}" role="img" aria-label="${esc(pollenPathLessons[index].caption)}" focusable="false">${art}</svg><figcaption>${key}<p>${esc(pollenPathLessons[index].caption)}</p></figcaption></figure>`;}

export function pollenPathPage(work,{announce=false}={}){const m=pollenPathModel(work);let body;if(m.page==='garden')body=`<h2 id="pollen-path-page-title" tabindex="-1">Model garden</h2><p>${esc(copy.instruction)}</p><section class="pollen-path-trail">${optionSelect('invitation','Choose a trail to try',pollenPathInvitations,work.invitation)}<p>${esc(m.invitation.prompt)}</p></section>${gardenFigure(m)}<div class="pollen-path-flower-controls">${flowerControls('A')}${flowerControls('B')}</div><p class="pollen-path-anatomy">${esc(copy.anatomy)}</p><section class="pollen-path-mark-panel" aria-label="Current model marks"><div class="pollen-path-legend">${legendMarks()}</div><p>${esc(copy.legend)}</p><p>${esc(copy.limit)}</p><p data-pollen-path-location><strong>${esc(m.location)}</strong></p><p data-pollen-path-body>${esc(m.bodyCaption)}</p>${m.stigmaCaptions.map((s,i)=>`<p data-pollen-path-stigma="${i?'B':'A'}">${esc(s)}</p>`).join('')}</section><p id="pollen-path-status" class="pollen-path-status" data-pollen-path-status${announce?' aria-live="polite" aria-atomic="true" data-pollen-path-announce':''}>${announce?'':esc(m.status)}</p><div class="pollen-path-actions">${button('clean','Use a clean paper visitor')}<div class="pollen-path-fresh">${button('fresh-request','Begin a fresh model')}${m.confirmFresh?`<div class="pollen-path-confirm"><p>${esc(copy.confirm)}</p><div class="pollen-path-actions">${button('fresh-confirm','Clear model marks')}${button('fresh-cancel','Keep this model')}</div></div>`:''}</div></div><section class="pollen-path-recent"><h3>Last eight model actions</h3>${m.recent.length?`<ol>${m.recent.map(s=>`<li>${esc(s)}</li>`).join('')}</ol>`:'<p>No model actions yet.</p>'}<p>${esc(copy.recentNote)}</p></section>`;
else body=`<h2 id="pollen-path-page-title" tabindex="-1">See why</h2>${optionSelect('lesson','Choose a teaching card',pollenPathLessons,work.lesson)}<div class="pollen-path-actions pollen-path-lesson-navigation">${button('lesson','Previous',work.lesson-1,work.lesson===0?'disabled':'')}${button('lesson','Next',work.lesson+1,work.lesson===3?'disabled':'')}</div><article class="pollen-path-lesson"><p class="pollen-path-worked-label">Worked picture · not your model</p><h3 id="pollen-path-lesson-title" tabindex="-1">${esc(m.lesson.title)}</h3><p>${esc(m.lesson.text)}</p>${workedFigure(work.lesson)}</article>`;
return `<div class="ll-page pollen-path-page" data-pollen-path-root><header><div class="pollen-path-actions">${button('back','Back to Living Layers')}<button type="button" class="secondary" data-pollen-path-hear data-speak="">Hear this page</button></div><h1 id="pollen-path-title" tabindex="-1">${esc(copy.title)}</h1><p>${esc(copy.intro)}</p></header><nav class="pollen-path-actions pollen-path-pages" aria-label="Pollen Path pages">${button('page','Model garden','garden',`aria-pressed="${m.page==='garden'}"`)}${button('page','See why','learn',`aria-pressed="${m.page==='learn'}"`)}</nav>${body}<footer><p>${esc(copy.lifetime)}</p></footer></div>`;}

export function bindPollenPath(work,ctx){const root=document.querySelector('[data-pollen-path-root]');if(!root)return;const live=n=>root.isConnected&&root.contains(n)&&ctx.live(n);const guard=(n,e)=>{if(!live(n)||n.disabled||n.getAttribute('aria-disabled')==='true'){e.preventDefault();e.stopImmediatePropagation();return false;}return true;};
for(const n of root.querySelectorAll('button,select')){n.addEventListener('click',e=>{if(!guard(n,e))return;if(n.matches('select'))return;ctx.stopSpeech?.();ctx.stopSound?.();if(n.matches('[data-pollen-path-hear]')){n.dataset.speak=pollenPathNarration(work);return;}e.preventDefault();apply(n,n.dataset.pollenPathValue);},{capture:true});if(n.matches('select'))n.addEventListener('change',e=>{if(!guard(n,e))return;ctx.stopSpeech?.();ctx.stopSound?.();apply(n,n.value);},{capture:true});}
function apply(n,value){const action=n.dataset.pollenPathAction;if(action==='back'){ctx.change(changePollenPath(work,'fresh-cancel'),'fresh-cancel');ctx.back();return;}if(action==='invitation'||action==='lesson')value=Number(value);const next=changePollenPath(work,action,value);if(next===work)return;ctx.change(next,action);ctx.render();const focus=action==='page'?'#pollen-path-page-title':action==='lesson'?'#pollen-path-lesson-title':action==='fresh-confirm'?'#pollen-path-title':action==='fresh-cancel'?'[data-pollen-path-action="fresh-request"]':n.tagName==='SELECT'?`select[data-pollen-path-action="${action}"]`:`button[data-pollen-path-action="${action}"][data-pollen-path-value="${CSS.escape(n.dataset.pollenPathValue)}"]`;ctx.focus?.(focus);}
const status=root.querySelector('[data-pollen-path-announce]');if(status)queueMicrotask(()=>{if(live(status))status.textContent=pollenPathModel(work).status;});}
